// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @notice Minimal interface for the VotingEscrow used by the GaugeController.
interface IYBVotingEscrowForGaugeController {
    struct Point {
        uint256 bias;
        uint256 slope;
    }

    function get_last_user_slope(address addr) external view returns (int256);
    function get_last_user_point(address addr) external view returns (uint256 bias, uint256 slope);
    function locked__end(address addr) external view returns (uint256);
    function transfer_clearance_checker() external view returns (address);
}

/// @notice Minimal interface for gauge contracts that expose an adjustment factor.
interface IYBGauge {
    function get_adjustment() external view returns (uint256);
}

/// @notice Minimal interface for the governance/emissions token used by the GaugeController.
/// @dev In the original Vyper, the function is named `emit`. That collides with the `emit` keyword in Solidity.
///      If you need to call it from Solidity, you'll generally do a low-level call with the correct selector.
interface IYBGovernanceToken {
    //function emit(address owner, uint256 rate_factor) external returns (uint256);
    function preview_emissions(uint256 t, uint256 rate_factor) external view returns (uint256);
    function transfer(address _to, uint256 _amount) external returns (bool);
}

/// @notice Gauge Controller interface (Yield Basis style).
interface IYBGaugeController {
    // =========================
    // Structs
    // =========================

    struct Point {
        uint256 bias;
        uint256 slope;
    }

    struct VotedSlope {
        uint256 slope;
        uint256 bias;
        uint256 power;
        uint256 end;
    }

    // =========================
    // Events
    // =========================

    event VoteForGauge(
        uint256 time,
        address user,
        address gauge_addr,
        uint256 weight
    );

    event NewGauge(address addr);

    event SetKilled(address gauge, bool is_killed);

    // =========================
    // Core Immutable Addresses
    // =========================

    function TOKEN() external view returns (IYBGovernanceToken);
    function VOTING_ESCROW() external view returns (IYBVotingEscrowForGaugeController);

    // =========================
    // Gauge Registry / State
    // =========================

    function n_gauges() external view returns (uint256);
    function gauges(uint256 index) external view returns (address);
    function is_killed(address gauge) external view returns (bool);

    // user -> gauge -> VotedSlope
    function vote_user_slopes(address user, address gauge)
        external
        view
        returns (uint256 slope, uint256 bias, uint256 power, uint256 end);

    // total vote power used by user (in bps, max 10000)
    function vote_user_power(address user) external view returns (uint256);

    // last vote timestamp per (user, gauge)
    function last_user_vote(address user, address gauge) external view returns (uint256);

    // =========================
    // Weights & Emissions Storage Views
    // =========================

    function point_weight(address gauge)
        external
        view
        returns (uint256 bias, uint256 slope);

    function time_weight(address gauge) external view returns (uint256);

    function gauge_weight(address gauge) external view returns (uint256);
    function gauge_weight_sum() external view returns (uint256);

    function adjusted_gauge_weight(address gauge) external view returns (uint256);
    function adjusted_gauge_weight_sum() external view returns (uint256);

    function specific_emissions() external view returns (uint256);
    function specific_emissions_per_gauge(address gauge) external view returns (uint256);
    function weighted_emissions_per_gauge(address gauge) external view returns (uint256);
    function sent_emissions_per_gauge(address gauge) external view returns (uint256);

    // =========================
    // Admin (Ownable)
    // =========================

    function owner() external view returns (address);
    function transfer_ownership(address new_owner) external;

    // =========================
    // Gauge Management
    // =========================

    function add_gauge(address gauge) external;

    function set_killed(address gauge, bool is_killed) external;

    // =========================
    // Voting
    // =========================

    /// @notice Allocate voting power for changing pool weights.
    /// @param _gauge_addrs Gauge addresses to vote for.
    /// @param _user_weights Weights in bps (0–10000) per gauge.
    function vote_for_gauge_weights(
        address[] calldata _gauge_addrs,
        uint256[] calldata _user_weights
    ) external;

    // =========================
    // Read Helpers
    // =========================

    /// @notice Get current gauge weight.
    function get_gauge_weight(address addr) external view returns (uint256);

    /// @notice Get relative gauge weight normalized to 1e18.
    function gauge_relative_weight(address gauge) external view returns (uint256);

    /// @notice Whether a ve-transfer is allowed for a given user (no active voting power).
    function ve_transfer_allowed(address user) external view returns (bool);

    /// @notice Preview emissions for a given gauge at a specific timestamp.
    function preview_emissions(address gauge, uint256 at_time) external view returns (uint256);

    // =========================
    // Checkpoint & Emissions
    // =========================

    /// @notice Checkpoint a gauge (updates weights/emissions).
    function checkpoint(address gauge) external;

    /// @notice Claim emissions for the calling gauge.
    /// @dev In Vyper this is `emit() -> uint256`. Name collides with Solidity keyword; if needed,
    ///      you may have to interact via low-level calls using the known selector.
    //function emit() external returns (uint256);
}

src/interfaces/yb/IYBTokenVoting.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IYBTokenVotingOption {
    function vote(
        uint256 _proposalId,
        uint8 _voteOption,
        bool _tryEarlyExecution
    ) external;
}
interface IYBTokenVoting {
    error AlreadyInitialized();
    error DaoUnauthorized(
        address dao,
        address where,
        address who,
        bytes32 permissionId
    );
    error DateOutOfBounds(uint64 limit, uint64 actual);
    error DelegateCallFailed();
    error FunctionDeprecated();
    error InvalidDecayMidpoint(uint32 decayMidpointBasisPoints);
    error InvalidTargetConfig(IPlugin.TargetConfig targetConfig);
    error MinDurationOutOfBounds(uint64 limit, uint64 actual);
    error NoVotingPower();
    error NonexistentProposal(uint256 proposalId);
    error ProposalAlreadyExists(uint256 proposalId);
    error ProposalCooldownNotMet(uint256 remainingCooldown);
    error ProposalExecutionForbidden(uint256 proposalId);
    error RatioOutOfBounds(uint256 limit, uint256 actual);
    error TokenClockMismatch();
    error VoteCastForbidden(
        uint256 proposalId,
        address account,
        IMajorityVoting.Tally votes
    );
    event AdminChanged(address previousAdmin, address newAdmin);
    event BeaconUpgraded(address indexed beacon);
    event CooldownSettingsUpdated(uint32 cooldownPeriod);
    event DecaySettingsUpdated(uint32 decayMidpointBasisPoints);
    event ExcludedFromSupply(address[] accounts);
    event Initialized(uint8 version);
    event MembersAdded(address[] members);
    event MembersRemoved(address[] members);
    event MembershipContractAnnounced(address indexed definingContract);
    event MetadataSet(bytes metadata);
    event ProposalCreated(
        uint256 indexed proposalId,
        address indexed creator,
        uint64 startDate,
        uint64 endDate,
        bytes metadata,
        Action[] actions,
        uint256 allowFailureMap
    );
    event ProposalExecuted(uint256 indexed proposalId);
    event TargetSet(IPlugin.TargetConfig newTargetConfig);
    event Upgraded(address indexed implementation);
    event VoteCast(
        uint256 indexed proposalId,
        address indexed voter,
        IMajorityVoting.Tally votes
    );
    event VotingMinApprovalUpdated(uint256 minApprovals);
    event VotingSettingsUpdated(
        uint8 votingMode,
        uint32 supportThreshold,
        uint32 minParticipation,
        uint64 minDuration,
        uint256 minProposerVotingPower
    );

    function CREATE_PROPOSAL_PERMISSION_ID() external view returns (bytes32);

    function EXECUTE_PROPOSAL_PERMISSION_ID() external view returns (bytes32);

    function SET_METADATA_PERMISSION_ID() external view returns (bytes32);

    function SET_TARGET_CONFIG_PERMISSION_ID() external view returns (bytes32);

    function UPDATE_VOTING_SETTINGS_PERMISSION_ID()
        external
        view
        returns (bytes32);

    function UPGRADE_PLUGIN_PERMISSION_ID() external view returns (bytes32);

    function canExecute(uint256 _proposalId) external view returns (bool);

    function canVote(
        uint256 _proposalId,
        address _account,
        uint8 _voteOption
    ) external view returns (bool);

    function canVote(
        uint256 _proposalId,
        address _account,
        IMajorityVoting.Tally memory _votes
    ) external view returns (bool);

    // function createProposal(
    //     bytes memory _metadata,
    //     Action[] memory _actions,
    //     uint256 _allowFailureMap,
    //     uint64 _startDate,
    //     uint64 _endDate,
    //     uint8 _voteOption,
    //     bool _tryEarlyExecution
    // ) external returns (uint256 proposalId);

    function createProposal(
        bytes memory _metadata,
        Action[] memory _actions,
        uint64 _startDate,
        uint64 _endDate,
        bytes memory _data
    ) external returns (uint256 proposalId);

    function customProposalParamsABI() external pure returns (string memory);

    function dao() external view returns (address);

    function execute(uint256 _proposalId) external;

    function grant(
        address _where,
        address _who,
        bytes32 _permissionId
    ) external;

    function revoke(
        address _where,
        address _who,
        bytes32 _permissionId
    ) external;

    function isGranted(
        address _where,
        address _who,
        bytes32 _permissionId,
        bytes memory _data
    ) external view returns (bool);

    function getCurrentTargetConfig()
        external
        view
        returns (IPlugin.TargetConfig memory);

    function getDecayMidpointBasisPoints() external view returns (uint32);

    function getMetadata() external view returns (bytes memory);

    function getProposal(uint256 _proposalId)
        external
        view
        returns (
            bool open,
            bool executed,
            MajorityVotingBase.ProposalParameters memory parameters,
            IMajorityVoting.Tally memory tally,
            Action[] memory actions,
            uint256 allowFailureMap,
            IPlugin.TargetConfig memory targetConfig
        );

    function getProposalCooldownPeriod() external view returns (uint32);

    function getTargetConfig()
        external
        view
        returns (IPlugin.TargetConfig memory);

    function getUserLastProposalTimestamp(address _user)
        external
        view
        returns (uint256);

    function getVotes(uint256 _proposalId, address _account)
        external
        view
        returns (IMajorityVoting.Tally memory);

    function getVotingToken() external view returns (address);

    function hasSucceeded(uint256 _proposalId) external view returns (bool);

    function implementation() external view returns (address);

    function initialize(
        address _dao,
        MajorityVotingBase.VotingSettings memory _votingSettings,
        address _token,
        IPlugin.TargetConfig memory _targetConfig,
        bytes memory _pluginMetadata,
        TokenVoting.ExtendedParams memory _extendedParams
    ) external;

    function isMember(address _account) external view returns (bool);

    function isMinApprovalReached(uint256 _proposalId)
        external
        view
        returns (bool);

    function isMinParticipationReached(uint256 _proposalId)
        external
        view
        returns (bool);

    function isSupportThresholdReached(uint256 _proposalId)
        external
        view
        returns (bool);

    function isSupportThresholdReachedEarly(uint256 _proposalId)
        external
        view
        returns (bool);

    function minApproval() external view returns (uint256);

    function minDuration() external view returns (uint64);

    function minParticipation() external view returns (uint32);

    function minProposerVotingPower() external view returns (uint256);

    function pluginType() external pure returns (uint8);

    function proposalCount() external view returns (uint256);

    function protocolVersion() external pure returns (uint8[3] memory);

    function proxiableUUID() external view returns (bytes32);

    function setMetadata(bytes memory _metadata) external;

    function setTargetConfig(IPlugin.TargetConfig memory _targetConfig)
        external;

    function supportThreshold() external view returns (uint32);

    function supportsInterface(bytes4 _interfaceId)
        external
        view
        returns (bool);

    function tokenIndexedByTimestamp() external view returns (bool);

    function totalVotingPower(uint256 _timePoint)
        external
        view
        returns (uint256);

    function updateCooldownSettings(uint32 _cooldownPeriod) external;

    function updateDecaySettings(uint32 _decayMidpointBasisPoints) external;

    function updateMinApprovals(uint256 _minApprovals) external;

    function updateVotingSettings(
        MajorityVotingBase.VotingSettings memory _votingSettings
    ) external;

    function upgradeTo(address newImplementation) external;

    function upgradeToAndCall(address newImplementation, bytes memory data)
        external
        payable;

    function vote(
        uint256 _proposalId,
        IMajorityVoting.Tally memory _votes,
        bool _tryEarlyExecution
    ) external;

    function votingMode() external view returns (uint8);
}

interface IPlugin {
    struct TargetConfig {
        address target;
        uint8 operation;
    }
}

interface IMajorityVoting {
    struct Tally {
        uint256 abstain;
        uint256 yes;
        uint256 no;
    }
}

interface MajorityVotingBase {
    struct ProposalParameters {
        uint8 votingMode;
        uint32 supportThreshold;
        uint64 startDate;
        uint64 endDate;
        uint64 snapshotTimepoint;
        uint256 minVotingPower;
    }

    struct VotingSettings {
        uint8 votingMode;
        uint32 supportThreshold;
        uint32 minParticipation;
        uint64 minDuration;
        uint256 minProposerVotingPower;
    }
}

interface TokenVoting {
    struct ExtendedParams {
        uint256 minApprovals;
        address[] excludedAccounts;
        uint32 decayMidpointBasisPoints;
        uint32 proposalCreationCooldownPeriod;
    }
}

struct Action {
    address to;
    uint256 value;
    bytes data;
}

